class Solution:
    def averageOfLevels(self, root: Optional[TreeNode]) -> List[float]:
        out, q = [], [root]
        while q:
            out.append(sum(n.val for n in q) / len(q))
            q = [c for n in q for c in (n.left, n.right) if c]
        return out

