function averageOfLevels(root) {
  const s = [], c = [];
  const go = (n, d) => { if (!n) return; if (s.length === d) { s.push(0); c.push(0); } s[d] += n.val; c[d]++; go(n.left, d + 1); go(n.right, d + 1); };
  go(root, 0); return s.map((x, i) => x / c[i]);
}
